-- CLASS SPHERE initial catalogue and timetable migration
-- Source: user master instruction and attached FET timetable image.
-- NULL means the image did not specify that value.
CREATE TABLE IF NOT EXISTS academic_years (id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, year_number TINYINT UNSIGNED NOT NULL UNIQUE, label VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS semesters (id SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, academic_year_id SMALLINT UNSIGNED NOT NULL, semester_number TINYINT UNSIGNED NOT NULL, UNIQUE KEY uq_year_semester (academic_year_id, semester_number), CONSTRAINT fk_sem_year FOREIGN KEY (academic_year_id) REFERENCES academic_years(id));
CREATE TABLE IF NOT EXISTS units (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, semester_id SMALLINT UNSIGNED NOT NULL, code VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, description TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_unit_semester FOREIGN KEY (semester_id) REFERENCES semesters(id));
CREATE TABLE IF NOT EXISTS lecturers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, display_name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS timetable_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, unit_id INT UNSIGNED NOT NULL, day_of_week VARCHAR(12) NOT NULL, starts_at TIME NOT NULL, ends_at TIME NOT NULL, lecturer_id INT UNSIGNED NULL, venue VARCHAR(80) NULL, class_type VARCHAR(20) NULL, source_label VARCHAR(80) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_timetable_unit FOREIGN KEY (unit_id) REFERENCES units(id), CONSTRAINT fk_timetable_lecturer FOREIGN KEY (lecturer_id) REFERENCES lecturers(id), KEY idx_timetable_day_time (day_of_week, starts_at));
